import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.C2TvIV46.js";const h=JSON.parse('{"title":"What is @blamnetwork/megalo?","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function s(l,a,n,g,d,c){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="what-is-blamnetwork-megalo" tabindex="-1">What is @blamnetwork/megalo? <a class="header-anchor" href="#what-is-blamnetwork-megalo" aria-label="Permalink to &quot;What is @blamnetwork/megalo?&quot;">​</a></h1><p><strong>@blamnetwork/megalo</strong> is a TypeScript library for working with Halo <strong>Megalo</strong> scripts — the text-based scripting language used in Halo: Reach gametypes and custom map variants.</p><h2 id="what-this-package-provides" tabindex="-1">What this package provides <a class="header-anchor" href="#what-this-package-provides" aria-label="Permalink to &quot;What this package provides&quot;">​</a></h2><ul><li><strong>Parser</strong> — turn Megalo source (<code>.txt</code>) into an AST (<a href="/MegaloEvolved/beta/docs/guide/parsing">Parsing source</a>).</li><li><strong>Compiler</strong> — build game variant or custom variant data from a program (<a href="/MegaloEvolved/beta/docs/guide/compiling">Compiling</a>).</li><li><strong>Decompiler</strong> — recover Megalo source from compiled variant data (<a href="/MegaloEvolved/beta/docs/guide/decompiling">Decompiling</a>).</li><li><strong>BLF integration</strong> — extract, patch, and round-trip gametypes inside BLF files via <a href="https://blam-network.github.io/blf/" target="_blank" rel="noreferrer">@blamnetwork/blf</a> (<a href="/MegaloEvolved/beta/docs/guide/gametypes">Gametypes &amp; BLF</a>).</li><li><strong>Megalo versions</strong> — Reach MCC and Xbox 360 TU1 (<a href="/MegaloEvolved/beta/docs/guide/megalo-versions">Megalo versions</a>).</li><li><strong>Language reference</strong> — Bungie Megalo scripting concepts and per-build action tables (<a href="/MegaloEvolved/beta/docs/language/">Megalo language</a>).</li></ul><p>Megalo struct layouts and BLF chunk I/O come from <code>@blamnetwork/blf</code> and <a href="https://www.npmjs.com/package/@craftycodie/cstruct" target="_blank" rel="noreferrer">@craftycodie/cstruct</a>, which npm installs automatically as dependencies.</p><h2 id="get-started" tabindex="-1">Get started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get started&quot;">​</a></h2><p>See <a href="/MegaloEvolved/beta/docs/guide/quick-start">Install &amp; quick start</a>.</p><p>Release history: <a href="/MegaloEvolved/beta/docs/changelog">Changelog</a>.</p>',8)])])}const m=e(i,[["render",s]]);export{h as __pageData,m as default};
